def _get_ext():
    global _ext
    if _ext is None:
        _ext = load_inline(
            name="hadamard_fwd_src",
            cpp_sources="void hadamard_fwd(torch::Tensor, torch::Tensor);",
            cuda_sources=_CUDA_SRC,
            functions=["hadamard_fwd"],
            with_cuda=True,
            verbose=False,
